      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax, region: "FR" });
    cart.add(product("a", 1000), 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
  });
});

describe("Cart - checkout()", () => {
  it("returns totals and lines for a basic checkout", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);

    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher: fetcher });
    expect(result.totals.subtotalCents).toBe(3000); // 1500 * 2
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
  });

  it("throws InventoryError when inventory check fails (available: false)", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 5);

    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 2,
        reason: "low stock",
      } satisfies InventoryDecision),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.unreachable("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(5);
      expect(err.available).toBe(2);
      expect(err.message).toBe("low stock");
    }
  });

  it("throws InventoryError on partial-stock denial (available true but availableQuantity < requested)", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 10);

    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      } satisfies InventoryDecision),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.unreachable("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(10);
      expect(err.available).toBe(3);
    }
  });

  it("passes when inventory is fully available", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);

    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 10,
      } satisfies InventoryDecision),
    };
    const result = await cart.checkout({ inventoryChecker: checker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider when supplied", async () => {
    const discount: DiscountPolicy = { computeDiscountCents: () => 500 };
    const shipping: ShippingCalculator = {
      computeShippingCents: () => 300,
    };
    const cart = new Cart({ discountPolicy: discount, shippingCalculator: shipping });
    cart.add(product("a", 5000), 2); // subtotal 10000

    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };
    const result = await cart.checkout({ asyncTaxProvider: provider });
    // discount 500, discounted = 9500, tax = floor(9500 * 0.08) = 760
    expect(result.totals.discountCents).toBe(500);
    expect(result.totals.taxCents).toBe(760);
    expect(result.totals.shippingCents).toBe(300);
    expect(result.totals.totalCents).toBe(9500 + 760 + 300);
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);

    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("rate service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider: provider })).rejects.toThrow(
      "rate service down",
    );
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);

    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price fetch failed")),
    };
    await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
      "price fetch failed",
    );
  });

  it("composes priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
    const discount: DiscountPolicy = { computeDiscountCents: () => 200 };
    const cart = new Cart({ discountPolicy: discount, region: "US-CA" });
    cart.add(product("a", 1000), 2);

    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1200),
    };
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const result = await cart.checkout({
      priceFetcher: fetcher,
      inventoryChecker: checker,
      asyncTaxProvider: provider,
    });
    // subtotal: 1200*2 = 2400, discount 200, discounted 2200
    // tax: floor(2200 * 0.0875) = floor(192.5) = 192
    expect(result.totals.subtotalCents).toBe(2400);
    expect(result.totals.discountCents).toBe(200);
    expect(result.totals.taxCents).toBe(192);
    expect(provider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("generates default reason when none provided by inventory checker", async () => {
    const cart = new Cart();
    cart.add(product("widget", 1000), 5);

    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
      } satisfies InventoryDecision),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.unreachable("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.message).toContain("widget");
      expect(err.available).toBeUndefined();
    }
  });
});

import { describe, it, expect } from "vitest";
import {
