describe("CompositeDiscountPolicy", () => {
  it("rejects an empty policy list", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      "CompositeDiscountPolicy requires at least one policy",
    );
  });

  describe("sum mode", () => {
    it("sums independent policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10000 * 10% = 1000, plus 200 = 1200
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });

    it("defaults to sum mode when mode is omitted", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps negative child results to 0 before summing", () => {
      const negativeMock = {
        computeDiscountCents: () => -100,
      };
      const composite = new CompositeDiscountPolicy(
        [negativeMock, new FixedAmountDiscountPolicy(300)],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // First: 10000 * 10% = 1000 → remaining 9000
      // Second: 9000 * 10% = 900 → total discount 1900
      expect(composite.computeDiscountCents(10000)).toBe(1900);
    });

    it("ordering matters in chain mode", () => {
      const a = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500), new PercentageDiscountPolicy(10)],
        "chain",
      );
      const b = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      // a: fixed 500 first → remaining 9500, then 10% of 9500 = 950 → total 1450
      // b: 10% of 10000 = 1000 first → remaining 9000, then fixed min(500,9000)=500 → total 1500
      expect(a.computeDiscountCents(10000)).toBe(1450);
      expect(b.computeDiscountCents(10000)).toBe(1500);
    });

    it("chain stops accumulating when remaining reaches 0", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(10000),
          new PercentageDiscountPolicy(50),
        ],
        "chain",
      );
      // First eats the full subtotal → remaining 0, second gets 0
      expect(composite.computeDiscountCents(5000)).toBe(5000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child results to 0", () => {
      const negativeMock = { computeDiscountCents: () => -50 };
      const composite = new CompositeDiscountPolicy(
        [negativeMock, new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // negative clamped to 0 → remaining stays 1000, then fixed 200
      expect(composite.computeDiscountCents(1000)).toBe(200);
    });
  });
});
