toolArgs.file_text:
import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it("returns 0 regardless of inputs", () => {
    expect(calc.computeTaxCents(10000, "US")).toBe(0);
    expect(calc.computeTaxCents(0, "FR")).toBe(0);
    expect(calc.computeTaxCents(-100, "GB")).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  it("rejects defaultRate < 0", () => {
    expect(() => new RegionalTaxCalculator({}, -0.01)).toThrow(RangeError);
  });

  it("rejects defaultRate > 1", () => {
    expect(() => new RegionalTaxCalculator({}, 1.01)).toThrow(RangeError);
  });

  it("rejects NaN defaultRate", () => {
    expect(() => new RegionalTaxCalculator({}, NaN)).toThrow(RangeError);
  });

  it("rejects a rate < 0 in the map", () => {
    expect(() => new RegionalTaxCalculator({ "US": -0.01 })).toThrow(RangeError);
  });

  it("rejects a rate > 1 in the map", () => {
    expect(() => new RegionalTaxCalculator({ "US": 1.5 })).toThrow(RangeError);
  });

  it("rejects a NaN rate in the map", () => {
    expect(() => new RegionalTaxCalculator({ "US": NaN })).toThrow(RangeError);
  });

  it("uses the region-specific rate when present", () => {
    const calc = new RegionalTaxCalculator({ "US-CA": 0.0875 });
    // 10000 * 0.0875 = 875
    expect(calc.computeTaxCents(10000, "US-CA")).toBe(875);
  });

  it("rounds down to nearest cent", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.07 });
    // 9999 * 0.07 = 699.93 → 699
    expect(calc.computeTaxCents(9999, "US")).toBe(699);
  });

  it("falls back to default rate for unknown region", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.10 }, 0.05);
    // 10000 * 0.05 = 500
    expect(calc.computeTaxCents(10000, "FR")).toBe(500);
  });

  it("defaults to 0 rate when no default specified and region unknown", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.10 });
    expect(calc.computeTaxCents(10000, "FR")).toBe(0);
  });

  it("returns 0 for zero taxable amount", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.10 });
    expect(calc.computeTaxCents(0, "US")).toBe(0);
  });

  it("returns 0 for negative taxable amount", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.10 });
    expect(calc.computeTaxCents(-500, "US")).toBe(0);
  });

  it("accepts boundary rates 0 and 1", () => {
    const calcZero = new RegionalTaxCalculator({}, 0);
    expect(calcZero.computeTaxCents(10000, "US")).toBe(0);

    const calcOne = new RegionalTaxCalculator({}, 1);
    expect(calcOne.computeTaxCents(10000, "US")).toBe(10000);
  });
});

describe("AsyncTaxCalculator", () => {
  it("returns 0 for non-positive taxable amount without calling provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(0, "US")).toBe(0);
    expect(await calc.computeTaxCents(-100, "US")).toBe(0);
    expect(provider.getRate).not.toHaveBeenCalled();
  });

  it("fetches rate and computes tax, rounding down", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const calc = new AsyncTaxCalculator(provider);
    // 9999 * 0.0875 = 874.9125 → 874
    expect(await calc.computeTaxCents(9999, "US-CA")).toBe(874);
    expect(provider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("throws RangeError when provider returns rate > 1", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(1.5),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(10000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError when provider returns negative rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(-0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(10000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError when provider returns NaN", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(NaN),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(10000, "US")).rejects.toThrow(RangeError);
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("network error")),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(10000, "US")).rejects.toThrow("network error");
  });
});

describe("totalLineWeightGrams", () => {
  it("returns 0 for empty lines", () => {
    expect(totalLineWeightGrams([])).toBe(0);
  });

  it("sums weight * quantity across lines", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100, weightGrams: 200 }, quantity: 3 },
      { product: { id: "b", name: "B", unitPriceCents: 100, weightGrams: 500 }, quantity: 2 },
    ];
    // 200*3 + 500*2 = 600 + 1000 = 1600
    expect(totalLineWeightGrams(lines)).toBe(1600);
  });

  it("treats undefined weightGrams as 0", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 5 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(0);
  });
});

