toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const line = (id: string, price: number, qty: number, weight?: number): CartLine => ({
  product: { id, name: id, unitPriceCents: price, weightGrams: weight },
  quantity: qty,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for any input", () => {
    expect(calc.computeShippingCents([line("a", 100, 1)], 100)).toBe(0);
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  it("rejects negative flatCents", () => {
    expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
  });

  it("rejects non-integer flatCents", () => {
    expect(() => new FlatShippingCalculator(9.5)).toThrow(RangeError);
  });

  it("rejects negative freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
  });

  it("rejects non-integer freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new FlatShippingCalculator(500);
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });

  it("returns flat fee for non-empty cart", () => {
    const calc = new FlatShippingCalculator(500);
    expect(calc.computeShippingCents([line("a", 100, 1)], 100)).toBe(500);
  });

  it("returns 0 when subtotal >= freeOverCents", () => {
    const calc = new FlatShippingCalculator(500, 5000);
    expect(calc.computeShippingCents([line("a", 100, 1)], 5000)).toBe(0);
    expect(calc.computeShippingCents([line("a", 100, 1)], 6000)).toBe(0);
  });

  it("returns flat fee when subtotal < freeOverCents", () => {
    const calc = new FlatShippingCalculator(500, 5000);
    expect(calc.computeShippingCents([line("a", 100, 1)], 4999)).toBe(500);
  });

  it("accepts freeOverCents of 0 (always free for non-empty carts)", () => {
    const calc = new FlatShippingCalculator(500, 0);
    expect(calc.computeShippingCents([line("a", 100, 1)], 0)).toBe(0);
  });
});

describe("WeightBasedShippingCalculator", () => {
  it("rejects empty brackets", () => {
    expect(() => new WeightBasedShippingCalculator([])).toThrow(
      "at least one weight bracket is required",
    );
  });

  it("rejects bracket with non-positive upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("rejects bracket with negative costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
    ).toThrow(RangeError);
  });

  it("rejects non-integer upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 10.5, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("rejects non-integer costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: 10.5 }]),
    ).toThrow(RangeError);
  });

  it("rejects negative overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 100, costCents: 100 }],
          -1,
        ),
    ).toThrow(RangeError);
  });

  it("rejects non-integer overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 100, costCents: 100 }],
          10.5,
        ),
    ).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });

  it("returns 0 when total weight is 0 (no weightGrams)", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([line("a", 100, 2)], 200)).toBe(0);
  });

  it("selects the first bracket whose upToGrams >= weight", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ]);
    expect(calc.computeShippingCents([line("a", 100, 1, 400)], 100)).toBe(300);
    expect(calc.computeShippingCents([line("a", 100, 1, 500)], 100)).toBe(300); // boundary
    expect(calc.computeShippingCents([line("a", 100, 1, 501)], 100)).toBe(600);
    expect(calc.computeShippingCents([line("a", 100, 1, 1000)], 100)).toBe(600); // boundary
    expect(calc.computeShippingCents([line("a", 100, 1, 1001)], 100)).toBe(1200);
  });

  it("sorts unsorted brackets internally", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 5000, costCents: 1200 },
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(calc.computeShippingCents([line("a", 100, 1, 400)], 100)).toBe(300);
    expect(calc.computeShippingCents([line("a", 100, 1, 1500)], 100)).toBe(1200);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ],
      2000,
    );
    expect(calc.computeShippingCents([line("a", 100, 1, 2000)], 100)).toBe(2000);
  });

  it("falls back to heaviest bracket cost when no overflowCostCents", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(calc.computeShippingCents([line("a", 100, 1, 5000)], 100)).toBe(600);
  });

  it("sums weight across multiple lines", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    // 200*2 + 300*1 = 700
    const lines: CartLine[] = [
      line("a", 100, 2, 200),
      line("b", 100, 1, 300),
    ];
    expect(calc.computeShippingCents(lines, 0)).toBe(600);
  });
});

