+      { upToGrams: 500, costCents: 300 },
+      { upToGrams: 1000, costCents: 600 },
+      { upToGrams: 5000, costCents: 1200 },
+    ]);
+    expect(calc.computeShippingCents([line("a", 100, 1, 400)], 100)).toBe(300);
+    expect(calc.computeShippingCents([line("a", 100, 1, 500)], 100)).toBe(300); // boundary
+    expect(calc.computeShippingCents([line("a", 100, 1, 501)], 100)).toBe(600);
+    expect(calc.computeShippingCents([line("a", 100, 1, 1000)], 100)).toBe(600); // boundary
+    expect(calc.computeShippingCents([line("a", 100, 1, 1001)], 100)).toBe(1200);
+  });
+
+  it("sorts unsorted brackets internally", () => {
+    const calc = new WeightBasedShippingCalculator([
+      { upToGrams: 5000, costCents: 1200 },
+      { upToGrams: 500, costCents: 300 },
+      { upToGrams: 1000, costCents: 600 },
+    ]);
+    expect(calc.computeShippingCents([line("a", 100, 1, 400)], 100)).toBe(300);
+    expect(calc.computeShippingCents([line("a", 100, 1, 1500)], 100)).toBe(1200);
+  });
+
+  it("uses overflow cost when weight exceeds all brackets", () => {
+    const calc = new WeightBasedShippingCalculator(
+      [
+        { upToGrams: 500, costCents: 300 },
+        { upToGrams: 1000, costCents: 600 },
+      ],
+      2000,
+    );
+    expect(calc.computeShippingCents([line("a", 100, 1, 2000)], 100)).toBe(2000);
+  });
+
+  it("falls back to heaviest bracket cost when no overflowCostCents", () => {
+    const calc = new WeightBasedShippingCalculator([
+      { upToGrams: 500, costCents: 300 },
+      { upToGrams: 1000, costCents: 600 },
+    ]);
+    expect(calc.computeShippingCents([line("a", 100, 1, 5000)], 100)).toBe(600);
+  });
+
+  it("sums weight across multiple lines", () => {
+    const calc = new WeightBasedShippingCalculator([
+      { upToGrams: 500, costCents: 300 },
+      { upToGrams: 1000, costCents: 600 },
+    ]);
+    // 200*2 + 300*1 = 700
+    const lines: CartLine[] = [
+      line("a", 100, 2, 200),
+      line("b", 100, 1, 300),
+    ];
+    expect(calc.computeShippingCents(lines, 0)).toBe(600);
+  });
+});
